Here's a simple JavaScript function that will switch the order of adjectives in a sentence:

```javascript
function swapAdjectives(sentence) {
  const words = sentence.split(" ");
  const adjectives = [];

  for (let i = 0; i < words.length; i++) {
    if (words[i].match(/^(\w+)\b\s*$/)) {
      adjectives.push(words[i]);
    }
  }

  if (adjectives.length > 1) {
    return `${adjectives[1]} ${adjectives[0]} ${words.slice(2).join(" ")}`;
  } else {
    return sentence;
  }
}

const originalSentence = "Beautiful green trees are in the park";
const modifiedSentence = swapAdjectives(originalSentence);
console.log(modifiedSentence); // Output: Green beautiful trees are in the park
```

