        {
            float amplitude = Mathf.Abs(audioData[i]);
            if (amplitude > maxAmplitude)
            {
                maxAmplitude = amplitude;
            }
        }

        for (int i = 0; i < audioData.Length; i++)
        {
            float normalizedAmplitude = audioData[i] / maxAmplitude;
            int colorIndex = (int)(normalizedAmplitude * colors.Length);
            transform.GetChild(i).GetComponent<Renderer>().material.color = colors[colorIndex];
        }
    }
}
```
This script uses the AudioSource component to get the audio spectrum data. It then normalizes the amplitude of each frequency and assigns a color to each frequency based on its amplitude. The colors are defined in the `colors` array.

To use this script, attach it to a GameObject in your scene and set the AudioSource component to the audio file you want to visualize. You can also adjust the `frequencyThreshold` variable to control the sensitivity of the visualization.

