```c
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    char *arg_str = malloc(argc * sizeof(char*));
    if (arg_str == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    for (int i = 0; i < argc; i++) {
        strcat(arg_str, argv[i]);
        if (i != argc - 1) {
