import re

def english_number_to_words(n):
    if n == 0:
        return "zero"
    elif n > 0:
        digits = [int(d) for d in str(n)]
        words = []
        for i, d in enumerate(digits):
            if d == 1:
                words.append("one")
            elif d == 2:
                words.append("two")
            elif d == 3:
                words.append("three")
            elif d == 4:
                words.append("four")
            elif d == 5:
                words.append("five")
            elif d == 6:
                words.append("six")
            elif d == 7:
                words.append("seven")
            elif d == 8:
                words.append("eight")
            elif d == 9:
                words.append("nine")
            elif d == 0:
                pass
            else:
                raise ValueError("Invalid digit")
        return " ".join(reversed(words))
    else:
        return f"minus {english_number_to_words(-n)}"

