      console.error(`Redis client is not alive: ${err}`);
      return false;
    }
  }

  async get(key) {
    const result = await this.client.get(key);
    return result;
  }

  async set(key, value, duration) {
    await this.client.set(key, value, {
      EX: duration,
    });
  }

  async del(key) {
    await this.client.del(key);
  }
}

